python3 - <<'EOF'
import json
r=json.load(open('/tmp/opensip-design-corrections/consumer-b.v14/requirements.json'))
print(type(r), list(r.keys()) if isinstance(r,dict) else len(r))
def walk(o,d=0):
    if d>2: return
    if isinstance(o,dict):
        for k,v in o.items():
            print('  '*d+str(k), type(v).__name__, (len(v) if isinstance(v,(list,dict)) else repr(v)[:120]))
            if isinstance(v,(dict,list)) and d<1: walk(v,d+1)
    elif isinstance(o,list):
        print('  '*d+f'[list {len(o)}]')
        if o: walk(o[0],d+1)
walk(r)
EOF

