"""Independent evaluator3 implementation, from the normative kit only.

Owners read:
  foundation/evaluator-composition-contract.v3.md  sections 1-9 (field derivation)
  foundation/atom-evaluation-contract.v1.md        sections 1-9 (atom law)
  foundation/enumeration-contract.v1.md / enumeration-plan.schema.v1.json
  foundation/evaluator-projection-registry.v1.json (relations, owedPartitions, capabilityForRelation)
  foundation/relation-payload-schemas.v2.json      (ladders, subjectKind)
  native/native-evidence.schemas.v2.json           (CoverageResultV3, sufficiency inputs)
  product-v1/identity-and-evidence.md section 4    (determinate-evidence table, Kleene)
  product-v1/native-evidence.md section 4.6        (sufficiency_v2 ordered steps)

It reads ONLY retained inputs. It never reads a claimed finding, witness value, verdict,
count, or any caller-supplied truth flag.
"""
import json
import os
import sys

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import opensip_core as K
import opensip_schema as S
import opensip_build as B

KIT = S.KIT

TRUE, FALSE, UNK = 'true', 'false', 'indeterminate'

POLICY_UNIVERSE_MAP = {
    'typescript': 'native.semantic-universe.typescript.v2',
    'rust': 'native.semantic-universe.rust.v2',
    'syntax': 'native.semantic-universe.syntax.v2',
}
RESOLVED_RUNGS = {'resolved-target', 'resolved-binding', 'resolved-callee', 'checked',
                  'from-resolved-calls'}


def _reg(path, key):
    return json.load(open(KIT + '/' + S.doc_path(path)))[key]


class EvalError(Exception):
    pass


class Inputs:
    """The admitted retained input closure handed to the evaluator."""

    def __init__(self, store, plan_id, plan, exec_plan_id, evaluator_closure,
                 policy, rule_program, waivers, emission_plan, enumeration_plan,
                 inventories, views, facts, scopes, coverages, coverage_payloads,
                 fact_payloads, universes, contexts, execution_inputs, imports=None,
                 import_payloads=None, import_observations=None, import_flags=None,
                 import_scopes=None, snapshot=None, detector_projection_closure=None):
        self.store = store
        self.plan_id = plan_id
        self.plan = plan
        self.exec_plan_id = exec_plan_id
        self.evaluator_closure = evaluator_closure
        self.policy = policy
        self.rule_program = rule_program
        self.waivers = waivers
        self.emission_plan = emission_plan
        self.enumeration_plan = enumeration_plan
        self.inventories = inventories          # list of (digest, SubjectInventoryV1)
        self.views = views                      # {view2 id: record}
        self.facts = facts                      # {fact2 id: record}
        self.scopes = scopes                    # {scope2 id: record}
        self.coverages = coverages              # {coverage2 id: record}
        self.coverage_payloads = coverage_payloads   # {coverage2 id: payload}
        self.fact_payloads = fact_payloads       # {fact2 id: payload}
        self.universes = universes               # {bare hex: (domain, record)}
        self.contexts = contexts                 # {bare hex: (domain, record)}
        self.execution_inputs = execution_inputs
        self.imports = imports or {}
        self.import_payloads = import_payloads or {}
        self.import_observations = import_observations or {}
        self.import_flags = import_flags or {}
        self.import_scopes = import_scopes or {}
        self.snapshot = snapshot
        self.detector_projection_closure = detector_projection_closure
        self.relreg = _reg(B.RELATION_DOC, 'x-opensip-relation-registry')
        self.projreg = json.load(open(KIT + '/' + S.doc_path(
            'foundation/evaluator-projection-registry.v1.json')))

    # ---------------- convenience
    def ladder(self, relation):
        row = self.relreg['relations'].get(relation)
        if not row or not row.get('ladder'):
            raise EvalError('RELATION_LADDER_ABSENT:%s' % relation)
        return row['ladder']

    def rung_index(self, relation, rung):
        lad = self.ladder(relation)
        if rung not in lad:
            raise EvalError('RUNG_NOT_IN_LADDER:%s@%s' % (relation, rung))
        return lad.index(rung)

    def subject_kind_of_relation(self, relation):
        return self.projreg['relations'][relation]['sourceSubjectKind']

    def source_field(self, relation):
        return self.projreg['relations'][relation]['sourceField']

    def capability_for_relation(self, relation):
        return self.projreg['capabilityForRelation'][relation]


# ---------------------------------------------------------------- node addressing
def address_nodes(node, addr='p'):
    """program-predicate address law: root `p`; i-th operand of and/or at `a` is `a.i`
    (zero-based, shortest decimal, no leading zero); the operand of `not` at `a` is `a.0`."""
    out = [(addr, node)]
    op = node['op']
    if op in ('and', 'or'):
        for i, ch in enumerate(node['operands']):
            out += address_nodes(ch, '%s.%d' % (addr, i))
    elif op == 'not':
        out += address_nodes(node['operand'], addr + '.0')
    return out


def child_addresses(node, addr):
    op = node['op']
    if op in ('and', 'or'):
        return ['%s.%d' % (addr, i) for i in range(len(node['operands']))]
    if op == 'not':
        return [addr + '.0']
    return []


def count_nodes(node):
    return len(address_nodes(node))


def count_atoms(node):
    return sum(1 for _, n in address_nodes(node)
               if n['op'] in ('exists', 'none', 'count-at-most', 'all-covered'))


# ---------------------------------------------------------------- subject enumeration
def subject_id(universe_hex, kind, native_id, manifest_path=None):
    rec = {'schemaVersion': 3, 'universe': universe_hex, 'kind': kind,
           'nativeSubjectId': native_id}
    if kind == 'package':
        rec['packageManifestPath'] = manifest_path
    return K.ID('evaluation-subject', rec), rec


def glob_match(pattern, path):
    """workflows_model.v1.glob_match semantics named by the atom contract: `**/*.ts`
    matches root `a.ts`. Implemented as a segment matcher where `**` matches zero or
    more segments and `*` matches within one segment."""
    import re as _re

    def seg_re(seg):
        out = ''
        for ch in seg:
            if ch == '*':
                out += '[^/]*'
            elif ch == '?':
                out += '[^/]'
            else:
                out += _re.escape(ch)
        return out

    parts = pattern.split('/')
    rx = []
    for i, seg in enumerate(parts):
        if seg == '**':
            rx.append('(?:[^/]+/)*')
        else:
            rx.append(seg_re(seg) + ('/' if i < len(parts) - 1 else ''))
    full = '^' + ''.join(rx) + '$'
    full = full.replace('(?:[^/]+/)*/', '(?:[^/]+/)*')
    return bool(_re.match(full, path))


def path_selected(rule, scope_doc, path):
    """include absent or [] means all paths; exclusion wins; optional ScopeDocumentV1
    intersects its include/exclude globs as well (composition section 2)."""
    se = rule['subjectEnumeration']
    inc, exc = se.get('include'), se.get('exclude') or []
    if inc:
        if not any(glob_match(g, path) for g in inc):
            return False
    if any(glob_match(g, path) for g in exc):
        return False
    if scope_doc:
        if scope_doc.get('include'):
            if not any(glob_match(g, path) for g in scope_doc['include']):
                return False
        if any(glob_match(g, path) for g in scope_doc.get('exclude') or []):
            return False
    return True


PRIMARY_KIND = {'file': 'file', 'symbol': 'symbol', 'package': 'package', 'export': 'symbol'}


def relevant_inventories(inp, rule):
    """Every retained inventory whose `kind` equals the rule primary kind and whose cell
    languageMode maps to the rule's portable universe domain (composition 9.5)."""
    want_kind = PRIMARY_KIND[rule['subjectEnumeration']['subjectKind']]
    want_domain = POLICY_UNIVERSE_MAP.get(rule['subjectEnumeration']['universe'])
    if want_domain is None:
        raise EvalError('POLICY_UNIVERSE_TOKEN_UNKNOWN:%s'
                        % rule['subjectEnumeration']['universe'])
    lm = _reg(B.IDENTITY_DOC, 'x-opensip-digest-domains')['languageModes']['map']
    cells = inp.enumeration_plan['cells']
    out = []
    for dig, invrec in inp.inventories:
        if invrec['kind'] != want_kind:
            continue
        cell = cells[invrec['cellOrdinal']]
        if lm.get(cell['languageMode']) != want_domain.split('.')[-2]:
            # map values are 'typescript'|'rust'|'syntax'; domain tail is e.g. 'syntax'
            pass
        mode_lang = lm.get(cell['languageMode'])
        if POLICY_UNIVERSE_MAP.get(mode_lang) != want_domain:
            continue
        out.append((dig, invrec, cell))
    return out, want_kind, want_domain


def enumerate_subjects(inp, rule, scope_doc):
    """composition section 2 + 9.5. Returns (selected, unresolved, inv_refs,
    incomplete_refs, deficiencies, state)."""
    rel_inv, want_kind, want_domain = relevant_inventories(inp, rule)
    defs_ = []
    inv_refs = [{'domain': 'subject-inventory', 'digest': d} for d, _, _ in rel_inv]
    incomplete = [{'domain': 'subject-inventory', 'digest': d}
                  for d, r, _ in rel_inv if r['state'] != 'complete']
    if not rel_inv:
        defs_.append({'source': 'enumeration', 'cause': 'no-covering-program',
                      'subjectId': None, 'predicateId': None, 'inputRefs': [],
                      'evidenceKind': None, 'nativeCause': None, 'universe': None})
    selected, unresolved = [], []
    want_exported = rule['subjectEnumeration']['subjectKind'] == 'export'
    for dig, invrec, cell in rel_inv:
        ref = {'domain': 'subject-inventory', 'digest': dig}
        if invrec['state'] != 'complete':
            defs_.append({'source': 'enumeration', 'cause': 'incomplete-inventory',
                          'subjectId': None, 'predicateId': None, 'inputRefs': [ref],
                          'evidenceKind': None, 'nativeCause': invrec.get('nativeCause'),
                          'universe': None})
            if invrec.get('deficiency') == 'source-syntax-invalid':
                defs_.append({'source': 'enumeration', 'cause': 'source-syntax-invalid',
                              'subjectId': None, 'predicateId': None, 'inputRefs': [ref],
                              'evidenceKind': None, 'nativeCause': None, 'universe': None})
        uni = cell['programBindings'][invrec['programOrdinal']]['universe']
        for row in invrec['rows']:
            if not path_selected(rule, scope_doc, row['path']):
                continue
            sid, srec = subject_id(uni, row['kind'], row['nativeSubjectId'],
                                   row['path'] if row['kind'] == 'package' else None)
            if want_exported:
                e = row.get('exported')
                if e == 'exported':
                    selected.append((sid, srec, row, uni, ref))
                elif e == 'unknown':
                    unresolved.append(sid)
                    defs_.append({'source': 'enumeration',
                                  'cause': 'unknown-export-membership',
                                  'subjectId': sid, 'predicateId': None,
                                  'inputRefs': [ref], 'evidenceKind': None,
                                  'nativeCause': None, 'universe': None})
                continue
            selected.append((sid, srec, row, uni, ref))
    # union duplicates only for the SAME (universe, kind, nativeSubjectId[, manifestPath])
    ded = {}
    for t in selected:
        ded.setdefault(t[0], t)
    selected = [ded[k] for k in sorted(ded, key=lambda s: K.C(s))]
    state = 'incomplete' if defs_ else 'complete'
    return selected, sorted(set(unresolved), key=lambda s: K.C(s)), \
        K.cset(inv_refs), K.cset(incomplete), defs_, state


# ---------------------------------------------------------------- native atom
def subject_occupies(inp, relation, fact_id, subject_rec):
    """Source occupancy: the registered payload field for this relation
    (evaluator-projection-registry relations[].sourceField)."""
    f = inp.facts[fact_id]
    pay = inp.fact_payloads[fact_id]
    field = inp.source_field(relation)
    if field == 'path':
        return pay.get('path') == subject_rec['nativeSubjectId']
    if field == 'anchors[0].path':
        return bool(f['anchors']) and f['anchors'][0]['path'] == subject_rec['nativeSubjectId']
    if field == 'declared':
        return pay.get('declared') == subject_rec['nativeSubjectId']
    if field == 'packageName':
        return (pay.get('packageName') == subject_rec['nativeSubjectId']
                and pay.get('manifestPath') == subject_rec.get('packageManifestPath'))
    if field == 'referrer':
        return pay.get('referrer') == subject_rec['nativeSubjectId']
    if field == 'symbol':
        return pay.get('symbol') == subject_rec['nativeSubjectId']
    raise EvalError('UNHANDLED_SOURCE_FIELD:%s:%s' % (relation, field))


def filter_value(inp, relation, fact_id, field):
    f = inp.facts[fact_id]
    pay = inp.fact_payloads[fact_id]
    spec = inp.projreg['relations'][relation]['filters'][field]
    if spec == 'forbidden':
        raise EvalError('ATOM_FILTER_FIELD_FORBIDDEN:%s.%s' % (relation, field))
    if spec == 'fact.resolution':
        return f['resolution']
    if spec == 'fact.confidenceMillionths':
        return f['confidenceMillionths']
    if spec == 'endpoint-universe-domain':
        dom, _ = inp.universes[f['sourceUniverse']]
        return dom
    if spec.startswith('payload.'):
        return pay.get(spec[len('payload.'):])
    if spec == 'fact.anchors[0].path':
        return f['anchors'][0]['path'] if f['anchors'] else None
    raise EvalError('UNHANDLED_FILTER_SPEC:%s' % spec)


def apply_filters(inp, relation, fact_id, filters):
    for flt in filters:
        v = filter_value(inp, relation, fact_id, flt['field'])
        cmp_, want = flt['cmp'], flt['value']
        if cmp_ == 'eq':
            ok = v == want
        elif cmp_ == 'neq':
            ok = v != want
        elif cmp_ == 'in':
            ok = v in want
        elif cmp_ == 'prefix':
            ok = isinstance(v, str) and v.startswith(want)
        elif cmp_ == 'glob':
            ok = isinstance(v, str) and glob_match(want, v)
        elif cmp_ == 'gte':
            ok = isinstance(v, int) and v >= want
        elif cmp_ == 'lte':
            ok = isinstance(v, int) and v <= want
        else:
            raise EvalError('UNHANDLED_CMP:%s' % cmp_)
        if not ok:
            return False
    return True


def view_entry_for(inp, view_id, relation, rung, source_u):
    """The view's Coverage entries at exactly (relation, rung, sourceUniverse)."""
    out = []
    for cid in inp.views[view_id]['coverageIds']:
        pay = inp.coverage_payloads[cid]
        key = pay['key']
        if (key['relation'] == relation and key['resolution'] == rung
                and key['sourceUniverse'] == source_u):
            out.append((cid, pay))
    return out


def sufficiency_v2(inp, relation, min_rung, entries, quantifier, completeness,
                   min_confidence=0, derivation_policy='any',
                   unresolved_policy='forbid', external_policy='forbid'):
    """native-evidence section 4.6, evaluated IN ORDER; every applicable cause is
    collected. Returns {satisfied, deficiency, causes, disclosures}."""
    causes, disclosures = [], []
    if not entries:
        causes.append('required-relation-missing')
        return {'satisfied': False, 'deficiency': 'required-relation-missing',
                'causes': causes, 'disclosures': disclosures}
    for cid, pay in entries:
        e = pay['entry']
        # step 2: rung below minResolution
        if inp.rung_index(relation, e['resolution']) < inp.rung_index(relation, min_rung):
            causes.append(e.get('deficiency') or 'required-relation-missing')
        # step 3
        if e['confidenceMillionths'] < min_confidence:
            causes.append('confidence-floor-unmet')
        # step 4
        if relation == 'types' and derivation_policy == 'declared-only' \
                and 'compiler-inferred' in e['derivationKinds']:
            causes.append('derivation-policy-unmet')
        # step 5
        if completeness == 'complete' and e['coverage'] != 'complete':
            causes.append(e.get('deficiency') or 'coverage-unknown')
        # step 6
        if quantifier == 'universal-negative':
            st = e['resolutionCompleteness']['state']
            if st in ('partial', 'not-attempted'):
                causes.append('resolution-incomplete')
            elif st == 'incomplete':
                if unresolved_policy == 'forbid':
                    causes.append('resolution-incomplete')
                else:
                    disclosures.append({'unresolved-edges':
                                        e['resolutionCompleteness']['unresolvedEdgeCount'],
                                        'classes':
                                        e['resolutionCompleteness']['unresolvedEdgeClasses']})
        # step 7 is an INCOMING-only concern (atom contract section 4: target_exported /
        # target_affected apply only to endpoint=target); outgoing predicates do not
        # inherit unrelated incoming closed-world.
    uniq = [c for i, c in enumerate(causes) if c not in causes[:i]]
    if uniq:
        return {'satisfied': False, 'deficiency': precedence_pick(uniq), 'causes': uniq,
                'disclosures': disclosures}
    return {'satisfied': True, 'deficiency': None, 'causes': [], 'disclosures': disclosures}


DEFICIENCY_PRECEDENCE = ['language-tier-unsupported', 'provider-unavailable',
                         'input-closure-incomplete', 'budget-exhausted',
                         'confidence-floor-unmet', 'derivation-policy-unmet',
                         'resolution-incomplete', 'external-consumers-unknown',
                         'required-relation-missing']


def precedence_pick(causes):
    for d in DEFICIENCY_PRECEDENCE:
        if d in causes:
            return d
    return causes[0]


def evaluate_native_atom(inp, atom, subject_rec, subject_id_, view_ids, rule_inv_refs):
    """Atom contract sections 3-5, OUTGOING endpoint (the endpoint this reconstruction
    exercises). Returns a dict with value, known/uncertain fact ids, coverageIds,
    scopeIds, causes, nativeDeficiencies."""
    relation, rung = atom['relation'], atom['minResolution']
    if rung not in inp.ladder(relation):
        raise EvalError('ATOM_MIN_RESOLUTION_NOT_IN_LADDER:%s@%s' % (relation, rung))
    if atom.get('endpoint', 'source') != 'source':
        raise EvalError('ATOM_ENDPOINT_NOT_EXERCISED_BY_THIS_RECONSTRUCTION')
    want_kind = inp.subject_kind_of_relation(relation)
    if subject_rec['kind'] != want_kind:
        raise EvalError('ATOM_KIND_INCOMPATIBLE:%s expects %s got %s'
                        % (relation, want_kind, subject_rec['kind']))
    U = subject_rec['universe']
    min_i = inp.rung_index(relation, rung)

    known, uncertain = [], []
    for fid, f in sorted(inp.facts.items()):
        if f['relation'] != relation or f['sourceUniverse'] != U:
            continue
        if inp.rung_index(relation, f['resolution']) < min_i:
            continue
        if not subject_occupies(inp, relation, fid, subject_rec):
            continue
        if not apply_filters(inp, relation, fid, atom.get('filters') or []):
            continue
        known.append(fid)
    known = K.cset_strings(known)

    # ---- containing scopes at the EXACT requested rung for this source universe
    containing, cov_ids, scope_ids, causes = [], [], [], []
    for sid, srec in sorted(inp.scopes.items()):
        if (srec['relation'] != relation or srec['resolution'] != rung
                or srec['sourceUniverse'] != U):
            continue
        if subject_in_scope(inp, relation, srec, subject_rec):
            containing.append(sid)
    paired = {}
    for cid, crec in sorted(inp.coverages.items()):
        paired.setdefault(crec['scopeId'], []).append(cid)
    entries = []
    for sid in containing:
        if sid not in paired:
            causes.append({'code': 'scope-without-coverage', 'nativeCause': None,
                           'universe': U})
            continue
        for cid in paired[sid]:
            pay = inp.coverage_payloads[cid]
            if (pay['key']['relation'] == relation
                    and pay['key']['resolution'] == rung
                    and pay['key']['sourceUniverse'] == U):
                entries.append((cid, pay))
                cov_ids.append(cid)
                scope_ids.append(sid)
    if not containing and not entries:
        causes.append({'code': 'missing-relation-coverage', 'nativeCause': None,
                       'universe': U})

    # ---- examination: independently enumerated source subjects must be covered
    uncovered = uncovered_expected(inp, relation, rung, U, containing, rule_inv_refs)
    if uncovered:
        causes.append({'code': 'uncovered-expected-source-subject', 'nativeCause': None,
                       'universe': U})

    # ---- disclose the Coverage entries' own deficiencies
    native_defs = []
    for cid, pay in entries:
        e = pay['entry']
        if e['coverage'] != 'complete':
            pass   # carried by sufficiency_v2 below
    op = atom['op']
    resolved = rung in RESOLVED_RUNGS
    quant = 'universal-negative' if (op in ('none', 'count-at-most')) else 'existential'
    if op == 'all-covered':
        quant = 'universal-negative' if resolved else 'existential'

    suff = sufficiency_v2(inp, relation, rung, entries, quant, 'complete')
    if not suff['satisfied'] and suff['deficiency']:
        native_defs.append(suff['deficiency'])

    complete_examination = (bool(entries) and not uncovered and not causes
                           and suff['satisfied'])

    # ---- determinate-evidence table (identity section 4 / composition section 3)
    if op == 'exists':
        value = TRUE if known else (FALSE if complete_examination else UNK)
    elif op == 'none':
        value = FALSE if known else (TRUE if complete_examination else UNK)
    elif op == 'count-at-most':
        n = atom['n']
        if len(known) > n:
            value = FALSE
        elif complete_examination:
            value = TRUE
        else:
            value = UNK
    elif op == 'all-covered':
        value = TRUE if suff['satisfied'] and bool(entries) else UNK
        if not entries:
            value = UNK
    else:
        raise EvalError('UNHANDLED_ATOM_OP:%s' % op)

    return {'value': value, 'kind': 'native-atom',
            'knownFactIds': known, 'uncertainFactIds': K.cset_strings(uncertain),
            'coverageIds': K.cset_strings(cov_ids), 'scopeIds': K.cset_strings(scope_ids),
            'causes': causes, 'nativeDeficiencies': native_defs,
            'countLimit': atom['n'] if op == 'count-at-most' else None,
            'coverageEntryDeficiencies': [
                (cid, inp.coverage_payloads[cid]['entry']['deficiency'],
                 inp.coverage_payloads[cid]['entry']['nativeCause'],
                 inp.coverage_payloads[cid]['key']['sourceUniverse'])
                for cid, _ in entries
                if inp.coverage_payloads[cid]['entry']['deficiency'] is not None],
            'sufficiency': suff}


def subject_in_scope(inp, relation, scope_rec, subject_rec):
    """relation registry subjectKindLaw: what a scope's `subjects` entries identify."""
    kind = inp.relreg['relations'][relation]['subjectKind']
    n = subject_rec['nativeSubjectId']
    if kind in ('source-path', 'package-name', 'symbol'):
        return n in scope_rec['subjects']
    raise EvalError('UNHANDLED_SUBJECT_KIND:%s' % kind)


def uncovered_expected(inp, relation, rung, U, containing, rule_inv_refs):
    """Missing expected source subjects of this universe (owedPartitions.outgoing
    examination). Expected source subjects come from the retained inventories of the
    relation's own source kind for this universe."""
    want_kind = inp.subject_kind_of_relation(relation)
    expected = set()
    cells = inp.enumeration_plan['cells']
    for dig, inv in inp.inventories:
        if inv['kind'] != want_kind:
            continue
        cell = cells[inv['cellOrdinal']]
        binding = cell['programBindings'][inv['programOrdinal']]
        if binding.get('universe') != U:
            continue
        if inp.capability_for_relation(relation) != cell['capabilityId']:
            continue
        for row in inv['rows']:
            expected.add(row['nativeSubjectId'])
    covered = set()
    for sid in containing:
        covered |= set(inp.scopes[sid]['subjects'])
    return sorted(expected - covered)

"""Composition of evaluator3 outputs from admitted retained inputs.

Implements evaluator-composition-contract.v3 sections 3, 4, 5, 9.1-9.7 exactly as written.
Reads no claimed output. Every field is derived.
"""
import json
import os
import sys

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import opensip_core as K
import opensip_schema as S
import opensip_build as B
import opensip_eval as E

TRUE, FALSE, UNK = E.TRUE, E.FALSE, E.UNK
SEVERITY_ORDER = {'note': 0, 'warning': 1, 'error': 2}


def kleene_and(vals):
    if FALSE in vals:
        return FALSE
    if all(v == TRUE for v in vals):
        return TRUE
    return UNK


def kleene_or(vals):
    if TRUE in vals:
        return TRUE
    if all(v == FALSE for v in vals):
        return FALSE
    return UNK


def kleene_not(v):
    return {TRUE: FALSE, FALSE: TRUE, UNK: UNK}[v]


def build_rule_program(policy):
    """composition 9.1: RuleProgramV2 is `{schemaVersion:2, policyDigest, rules:[{ruleId,
    ruleProgramRef, emitWhen} for each policy.rules member in policy order]}`."""
    return {'schemaVersion': 2, 'policyDigest': K.rec_digest(policy),
            'rules': [{'ruleId': r['ruleId'], 'ruleProgramRef': r['ruleProgramRef'],
                       'emitWhen': r['emitWhen']} for r in policy['rules']]}


def scope_document_parameter(inp, analysis_spec, store):
    """Recover the optional selected ScopeDocumentV1 analysis-spec parameter.
    The `parameter` payload class is keyed by the cited schemaDigest; ONE Plan selects at
    most one parameter per registered row (payload registry selectionCardinality)."""
    reg = E._reg(B.IDENTITY_DOC, 'x-opensip-payload-registry')['classes']['parameter']['rows']
    rows = {}
    for key, row in reg.items():
        rows[S.load_doc(row['document'])['sha256']] = (row['document'], row['selector'])
    picked = {}
    for p in analysis_spec['parameters']:
        if p['schemaDigest'] not in rows:
            raise E.EvalError('PAYLOAD_PARAMETER_SCHEMA_UNREGISTERED:%s' % p['schemaDigest'])
        doc, sel = rows[p['schemaDigest']]
        picked.setdefault((doc, sel), []).append(p)
    for k, v in picked.items():
        if len(v) > 1:
            raise E.EvalError('ANALYSIS_SPEC_PARAMETER_SELECTION_AMBIGUOUS:%s' % (k,))
    for (doc, sel), v in picked.items():
        if sel == '#/$defs/ScopeDocumentV1':
            b = store.get_blob(v[0]['payloadDigest'])
            if b is None:
                raise E.EvalError('PARAMETER_PAYLOAD_NOT_RETAINED')
            return json.loads(b.decode())
    return None


def compose(inp, store, emit_plan, exec_inputs_digest, snapshot_id):
    """Returns the complete composed output bundle, all derived."""
    policy = inp.policy
    rule_program = build_rule_program(policy)
    if K.rec_digest(rule_program) != K.rec_digest(inp.rule_program):
        raise E.EvalError('RULE_PROGRAM_NOT_THE_POLICY_PROJECTION')
    rule_program_digest = K.rec_digest(rule_program)
    if rule_program['policyDigest'] != K.rec_digest(policy):
        raise E.EvalError('RULE_PROGRAM_POLICY_DIGEST_MISMATCH')
    if inp.plan['policyDigest'] != rule_program['policyDigest']:
        raise E.EvalError('PLAN_POLICY_DIGEST_MISMATCH')

    # ---- EI = Cset(ExecutionInputsV1.selectedRefs U {XI})
    XI = {'domain': 'execution-inputs', 'digest': exec_inputs_digest}
    EI = K.cset(list(inp.execution_inputs['selectedRefs']) + [XI])
    forbidden = {'proof-bundle', 'finding', 'evaluation-seal', 'run', 'semantic-evidence'}
    for r in EI:
        if r['domain'] in forbidden:
            raise E.EvalError('PROOF_INPUT_REF_FORBIDDEN_DOMAIN:%s' % r['domain'])
    for iid in inp.plan['importIds']:
        if {'domain': 'import', 'digest': iid.split(':', 1)[1]} not in EI:
            raise E.EvalError('PLAN_IMPORT_NOT_IN_EVALUATION_INPUT_REFS:%s' % iid)

    scope_doc = scope_document_parameter(inp, inp.analysis_spec, store)

    emit_by_rule = {r['ruleId']: r for r in emit_plan['rules']}
    if sorted(emit_by_rule) != sorted(r['ruleId'] for r in policy['rules']):
        raise E.EvalError('EMISSION_PLAN_DOES_NOT_BIND_EVERY_POLICY_RULE')
    ns = {}
    for r in emit_plan['rules']:
        key = (r['ruleStableId'], r['semanticsMajor'])
        if key in ns:
            raise E.EvalError('FINGERPRINT_NAMESPACE_NOT_UNIQUE:%s' % (key,))
        ns[key] = r['ruleId']

    # ---- enumeration per rule
    enum_by_rule, enum_defs = {}, {}
    for r in policy['rules']:
        if not r['enabled']:
            enum_by_rule[r['ruleId']] = ([], [], [], [], 'disabled')
            enum_defs[r['ruleId']] = []
            continue
        sel, unres, inv_refs, inc_refs, defs_, state = E.enumerate_subjects(inp, r, scope_doc)
        enum_by_rule[r['ruleId']] = (sel, unres, inv_refs, inc_refs, state)
        enum_defs[r['ruleId']] = defs_

    # ---- budget preflight (composition section 3), checked unsigned 64-bit
    Sset = sum(len(enum_by_rule[r['ruleId']][0]) for r in policy['rules'] if r['enabled'])
    Fcnt = len(inp.facts)
    Icnt = sum(len(p.get('subjects', [])) if isinstance(p, dict) else 0
               for p in inp.import_payloads.values())
    Kcnt = len(inp.coverages)
    Ecnt = sum(len(i['rows']) for _, i in inp.inventories) + \
        sum(len(c['programBindings']) for c in inp.enumeration_plan['cells'])
    work = Ecnt
    for r in policy['rules']:
        if not r['enabled']:
            continue
        N = E.count_nodes(r['emitWhen'])
        A = E.count_atoms(r['emitWhen'])
        per = N + A * (Fcnt + Icnt + Kcnt)
        work += per * len(enum_by_rule[r['ruleId']][0])
        if work > 2 ** 64 - 1:
            raise E.EvalError('BUDGET_ARITHMETIC_OVERFLOW')
    budget = inp.plan['budget']['limit']
    budget_exhausted = work > budget

    witnesses, predicate_proofs, findings, finding_records = {}, [], {}, {}
    rule_results, waived = [], []
    rule_defs = {r['ruleId']: list(enum_defs[r['ruleId']]) for r in policy['rules']}

    if not budget_exhausted:
        for r in policy['rules']:
            if not r['enabled']:
                continue
            sel, unres, inv_refs, inc_refs, state = enum_by_rule[r['ruleId']]
            # required-import deficiencies (composition 9.5)
            plan_kinds = {inp.imports[i]['kind'] for i in inp.plan['importIds']} \
                if inp.plan['importIds'] else set()
            for eu in r.get('evidenceUse') or []:
                if eu['requirement'] == 'required' and eu['kind'] not in plan_kinds:
                    rule_defs[r['ruleId']].append(
                        {'source': 'import', 'cause': 'evidence-kind-unavailable',
                         'subjectId': None, 'predicateId': None, 'inputRefs': [],
                         'evidenceKind': eu['kind'], 'nativeCause': None, 'universe': None})
            for sid, srec, row, uni, inv_ref in sel:
                addressed = E.address_nodes(r['emitWhen'])
                values = {}
                # postorder: deepest addresses first
                for addr, node in sorted(addressed, key=lambda t: -len(t[0])):
                    pp, wit, defs_ = eval_node(inp, r, node, addr, sid, srec, values,
                                               EI, rule_program_digest, inv_refs)
                    values[addr] = pp['value']
                    witnesses[pp['witnessDigest']] = wit
                    predicate_proofs.append(pp)
                    rule_defs[r['ruleId']] += defs_
                root_val = values['p']
                if root_val == TRUE:
                    fid, frec, fparams, fkey = mint_finding(
                        inp, r, emit_by_rule[r['ruleId']], sid, srec, row, uni,
                        predicate_proofs, witnesses, EI)
                    findings[fid] = frec
                    finding_records[fid] = {'parameters': fparams, 'fingerprint': fkey}
                    if frec['correspondence']['state'] == 'unmatched':
                        rule_defs[r['ruleId']].append(
                            {'source': 'correspondence',
                             'cause': frec['correspondence']['reason'],
                             'subjectId': sid, 'predicateId': 'p',
                             'inputRefs': inv_refs, 'evidenceKind': None,
                             'nativeCause': None, 'universe': None})

    # ---- waiver membership (composition section 5)
    for fid, frec in findings.items():
        for w in inp.waivers['waivers']:
            t = w['target']
            if 'fingerprint' in t and frec['fingerprint'] == t['fingerprint']:
                waived.append(fid)
            elif ('ruleId' in t and t['ruleId'] == frec['ruleId']
                  and t['subjectPath'] == frec['subject']['logicalPath']):
                waived.append(fid)

    # ---- rule results
    for r in policy['rules']:
        rid = r['ruleId']
        sel, unres, inv_refs, inc_refs, state = enum_by_rule[rid]
        my_findings = K.cset_strings([f for f, v in findings.items() if v['ruleId'] == rid])
        if budget_exhausted and r['enabled']:
            rule_defs[rid].append({'source': 'execution', 'cause': 'work-budget-exhausted',
                                   'subjectId': None, 'predicateId': None, 'inputRefs': [],
                                   'evidenceKind': None, 'nativeCause': None,
                                   'universe': None})
        defs_ = K.cset(rule_defs[rid])
        if not r['enabled']:
            outcome, enum_rec = 'disabled', {'state': 'disabled', 'inventoryRefs': [],
                                             'selectedSubjectIds': [],
                                             'unresolvedSubjectIds': [],
                                             'incompleteInventoryRefs': []}
        else:
            enum_rec = {'state': state, 'inventoryRefs': inv_refs,
                        'selectedSubjectIds': K.cset_strings([s[0] for s in sel]),
                        'unresolvedSubjectIds': K.cset_strings(unres),
                        'incompleteInventoryRefs': inc_refs}
            gates = (r['gate'] and SEVERITY_ORDER[r['severity']]
                     >= SEVERITY_ORDER[policy['gateSeverityAtLeast']])
            live_unwaived = [f for f in my_findings if f not in waived]
            if not gates:
                outcome = 'pass'
            elif live_unwaived:
                outcome = 'fail'
            else:
                blocking = blocking_causes(r, predicate_proofs, witnesses, sel)
                if state != 'complete' or unres or blocking:
                    outcome = 'indeterminate'
                else:
                    outcome = 'pass'
        rule_results.append({'ruleId': rid, 'enumeration': enum_rec, 'outcome': outcome,
                             'findingIds': my_findings, 'deficiencies': defs_})
    rule_results.sort(key=lambda x: x['ruleId'].encode())

    # ---- executionDeficiencies bridge (composition 9.6)
    exec_defs = execution_deficiencies(inp, XI, EI, budget_exhausted)

    # ---- verdict (composition section 5 + 9.7)
    if any(rr['outcome'] == 'fail' for rr in rule_results):
        verdict = 'fail'
    elif any(rr['outcome'] == 'indeterminate' for rr in rule_results) or exec_defs:
        verdict = 'indeterminate'
    else:
        verdict = 'pass'

    proof = {
        'schemaVersion': 3, 'planId': inp.plan_id, 'executionPlanId': inp.exec_plan_id,
        'evaluatorClosure': inp.evaluator_closure,
        'ruleProgramDigest': rule_program_digest,
        'evaluationInputRefs': EI,
        'predicateProofs': sorted(
            predicate_proofs,
            key=lambda p: (p['ruleId'] + ',' + p['subjectId'] + ',' + p['predicateId']).encode()),
        'findingIds': K.cset_strings(list(findings)),
        'verdict': verdict,
        'evaluationState': 'budget-exhausted' if budget_exhausted else 'evaluated',
        'ruleResults': rule_results,
        'waivedFindingIds': K.cset_strings(waived),
        'executionDeficiencies': exec_defs,
        'executionInputsDigest': exec_inputs_digest,
    }
    if budget_exhausted:
        proof['predicateProofs'] = []
        proof['findingIds'] = []

    view_ids = K.cset_strings(['view2:' + r['digest'] for r in EI if r['domain'] == 'view'])
    cov = set()
    for v in view_ids:
        cov |= set(inp.views[v]['coverageIds'])
    cov |= {'coverage2:' + r['digest'] for r in EI if r['domain'] == 'coverage'}
    evidence = {'schemaVersion': 3, 'planId': inp.plan_id, 'viewIds': view_ids,
                'coverageIds': K.cset_strings(sorted(cov)),
                'importIds': K.cset_strings(inp.plan['importIds']),
                'findingIds': proof['findingIds'],
                'proofBundleId': K.ID('proof-bundle', proof)}
    seal = {'schemaVersion': 3, 'planId': proof['planId'],
            'executionPlanId': proof['executionPlanId'],
            'evidenceId': K.ID('semantic-evidence', evidence),
            'evaluatorClosure': proof['evaluatorClosure'],
            'policyDigest': inp.plan['policyDigest'],
            'proofBundleId': K.ID('proof-bundle', proof), 'verdict': proof['verdict']}
    run = {'schemaVersion': 3, 'projectId': inp.snapshot['projectId'],
           'snapshotId': inp.plan['snapshotId'], 'planId': proof['planId'],
           'evidenceId': seal['evidenceId'],
           'evaluationSealId': K.ID('evaluation-seal', seal),
           'capabilityManifestId': inp.plan['capabilityManifestId']}
    pol_deriv = {'schemaVersion': 3, 'planId': run['planId'],
                 'proofBundleId': seal['proofBundleId'],
                 'policyDigest': inp.plan['policyDigest'],
                 'waiverDigest': inp.plan['waiverDigest'], 'verdict': proof['verdict']}
    return {
        'ruleProgram': rule_program, 'ruleProgramDigest': rule_program_digest,
        'evaluationInputRefs': EI, 'proof': proof, 'proofId': K.ID('proof-bundle', proof),
        'witnesses': witnesses, 'findings': findings, 'findingAux': finding_records,
        'evidence': evidence, 'evidenceId': seal['evidenceId'],
        'seal': seal, 'sealId': run['evaluationSealId'],
        'run': run, 'runId': K.ID('run', run),
        'policyDerivation': pol_deriv,
        'policyDerivationId': K.ID('policy-derivation', pol_deriv),
        'budget': {'workUnits': work, 'planLimit': budget, 'exhausted': budget_exhausted,
                   'terms': {'E': Ecnt, 'F': Fcnt, 'I': Icnt, 'K': Kcnt,
                             'selectedSubjectsOverEnabledRules': Sset}},
        'scopeDocumentParameter': scope_doc,
    }


def eval_node(inp, rule, node, addr, sid, srec, values, EI, rule_program_digest, inv_refs):
    op = node['op']
    prog_pred = {'schemaVersion': 2, 'ruleProgramDigest': rule_program_digest,
                 'ruleId': rule['ruleId'], 'predicateId': addr, 'operation': op,
                 'nodeDigest': K.rec_digest(node)}
    ppd = K.rec_digest(prog_pred)
    defs_ = []
    if op in ('and', 'or', 'not'):
        kids = E.child_addresses(node, addr)
        vals = [values[k] for k in kids]
        value = (kleene_and(vals) if op == 'and'
                 else kleene_or(vals) if op == 'or' else kleene_not(vals[0]))
        child_defs = []
        wit = {'schemaVersion': 3, 'programPredicateDigest': ppd, 'matchingFactIds': [],
               'coverageIds': [], 'countLimit': None,
               'childPredicateIds': K.cset_strings(kids), 'matchingImportRows': [],
               'uncertainFactIds': [], 'uncertainImportRows': [],
               'deficiencies': K.cset(child_defs), 'kind': 'boolean'}
        scope_ids = []
        pp = {'ruleId': rule['ruleId'], 'subjectId': sid, 'predicateId': addr,
              'operation': op, 'inputRefs': EI, 'scopeIds': K.cset_strings(scope_ids),
              'value': value, 'witnessDigest': K.rec_digest(wit)}
        return pp, wit, defs_
    res = E.evaluate_native_atom(inp, node, srec, sid, None, inv_refs)
    for c in res['causes']:
        defs_.append({'source': 'native', 'cause': c['code'], 'subjectId': sid,
                      'predicateId': addr, 'inputRefs': EI, 'evidenceKind': None,
                      'nativeCause': c.get('nativeCause'), 'universe': c.get('universe')})
    for d in res['nativeDeficiencies']:
        defs_.append({'source': 'native', 'cause': d, 'subjectId': sid,
                      'predicateId': addr, 'inputRefs': EI, 'evidenceKind': None,
                      'nativeCause': None, 'universe': None})
    for cid, dfc, ncause, uni in res['coverageEntryDeficiencies']:
        defs_.append({'source': 'native', 'cause': dfc, 'subjectId': sid,
                      'predicateId': addr,
                      'inputRefs': [{'domain': 'coverage', 'digest': cid.split(':', 1)[1]}],
                      'evidenceKind': None, 'nativeCause': ncause, 'universe': uni})
    wit = {'schemaVersion': 3, 'programPredicateDigest': ppd,
           'matchingFactIds': res['knownFactIds'], 'coverageIds': res['coverageIds'],
           'countLimit': res['countLimit'], 'childPredicateIds': [],
           'matchingImportRows': [], 'uncertainFactIds': res['uncertainFactIds'],
           'uncertainImportRows': [], 'deficiencies': K.cset(defs_), 'kind': 'native-atom'}
    pp = {'ruleId': rule['ruleId'], 'subjectId': sid, 'predicateId': addr, 'operation': op,
          'inputRefs': EI, 'scopeIds': res['scopeIds'], 'value': res['value'],
          'witnessDigest': K.rec_digest(wit)}
    return pp, wit, defs_


def blocking_causes(rule, predicate_proofs, witnesses, sel):
    """Root-indeterminate gating relevance: for an indeterminate and/or node only its
    indeterminate children contribute blocking causes; a determinate root has no
    truth-blocking cause (composition section 3)."""
    out = []
    by = {}
    for pp in predicate_proofs:
        if pp['ruleId'] != rule['ruleId']:
            continue
        by.setdefault(pp['subjectId'], {})[pp['predicateId']] = pp
    for sid, nodes in by.items():
        root = nodes.get('p')
        if root is None or root['value'] != UNK:
            continue
        stack = ['p']
        while stack:
            a = stack.pop()
            pp = nodes[a]
            if pp['value'] != UNK:
                continue
            w = witnesses[pp['witnessDigest']]
            if w['kind'] == 'boolean':
                stack += list(w['childPredicateIds'])
            else:
                for d in w['deficiencies']:
                    if d['source'] in ('native', 'import'):
                        out.append(d['cause'])
    return out


def mint_finding(inp, rule, emit_row, sid, srec, row, uni, predicate_proofs, witnesses, EI):
    """composition 9.7 + section 4 declarative-subject-v1 emission profile."""
    mine = [pp for pp in predicate_proofs
            if pp['ruleId'] == rule['ruleId'] and pp['subjectId'] == sid]
    root = [pp for pp in mine if pp['predicateId'] == 'p'][0]
    known_facts, uncertain_facts, cov, imports_seen = set(), set(), set(), set()
    for pp in mine:
        w = witnesses[pp['witnessDigest']]
        known_facts |= set(w['matchingFactIds'])
        uncertain_facts |= set(w['uncertainFactIds'])
        cov |= set(w['coverageIds'])
    matching_fact_count = len(known_facts)
    matching_import_count = 0

    # discriminator: file/package use SHA256(C([])); symbol uses the detector's ordered
    # nonempty signatureTokens from the projection whose closureId equals ruleClosure
    if srec['kind'] in ('file', 'package'):
        disc = K.raw_sha256(K.C([]))
        reason = None
    else:
        proj = [p for p in row.get('projections', [])
                if p['closureId'] == emit_row['detectorClosure']]
        toks = proj[0]['signatureTokens'] if proj else []
        if not toks:
            disc, reason = None, 'projection-unavailable'
        else:
            disc, reason = K.raw_sha256(K.C(toks)), None
    fingerprint = None
    if reason is None:
        fp = {'schemaVersion': 2, 'ruleStableId': emit_row['ruleStableId'],
              'detectorSemanticsMajor': emit_row['semanticsMajor'],
              'subjectKey': {'language': row['subjectLanguage'], 'kind': srec['kind'],
                             'logicalPath': row['path'],
                             'qualifiedName': row['qualifiedName'],
                             'discriminator': disc},
              'relatedSubjectKeys': []}
        fingerprint = K.ID('finding-fingerprint', fp)
        fpkey = fp
    else:
        fpkey = None
    message_code = rule.get('messageCode') or rule['ruleId']
    params = {'schemaVersion': 2, 'messageCode': message_code,
              'parameters': {'ruleId': rule['ruleId'], 'subjectPath': row['path'],
                             'qualifiedName': row['qualifiedName'],
                             'subjectKind': srec['kind'],
                             'subjectLanguage': row['subjectLanguage'],
                             'matchingFactCount': matching_fact_count,
                             'matchingImportCount': matching_import_count}}
    ev = [{'domain': 'predicate-witness', 'digest': root['witnessDigest']}]
    for f in sorted(known_facts | uncertain_facts):
        ev.append({'domain': 'fact', 'digest': f.split(':', 1)[1]})
    for c in sorted(cov):
        ev.append({'domain': 'coverage', 'digest': c.split(':', 1)[1]})
    for r in EI:
        if r['domain'] == 'import':
            ev.append({'domain': 'import', 'digest': r['digest']})
    finding = {'schemaVersion': 3, 'fingerprint': fingerprint,
               'ruleClosure': emit_row['detectorClosure'], 'subjectId': sid,
               'messageCode': message_code, 'parameterDigest': K.rec_digest(params),
               'severity': rule['severity'], 'evidenceRefs': K.cset(ev),
               'ruleId': rule['ruleId'],
               'subject': {'language': row['subjectLanguage'], 'kind': srec['kind'],
                           'logicalPath': row['path'],
                           'qualifiedName': row['qualifiedName']},
               'correspondence': {'state': 'matched' if fingerprint else 'unmatched',
                                  'reason': reason}}
    return K.ID('finding', finding), finding, params, fpkey


def execution_deficiencies(inp, XI, EI, budget_exhausted):
    """composition 9.6. Internal requiredCellDeficiencies rows are derived here from the
    retained ExecutionInputsV1 cellOutcomes / nativeCoverageAccounts, NOT asserted."""
    reg = E._reg(B.IDENTITY_DOC, 'x-opensip-evaluator-deficiency-registry')
    exec_members = set(reg['sources']['execution'])
    rows = []
    ei = inp.execution_inputs
    cells = inp.enumeration_plan['cells']
    for co in ei['cellOutcomes']:
        if not co['required']:
            continue
        if co['state'] == 'complete':
            continue
        originating = []
        for d in co['inventoryDigests']:
            originating.append({'domain': 'subject-inventory', 'digest': d})
        for acc in ei['nativeCoverageAccounts']:
            if acc['cellOrdinal'] != co['cellOrdinal'] or acc['programOrdinal'] != co['programOrdinal']:
                continue
            for cid in acc['coverageIds']:
                originating.append({'domain': 'coverage', 'digest': cid})
        if co['candidateResultDigest']:
            originating.append({'domain': 'candidate-producer-result',
                                'digest': co['candidateResultDigest']})
        d = co['deficiency']
        if d in exec_members:
            cause = d
        elif d is None or d == 'source-syntax-invalid':
            cause = 'required-cell-unsatisfied'
        else:
            raise E.EvalError('EVALUATOR_EXECUTION_CAUSE_UNREGISTERED:%s' % d)
        rows.append({'source': 'execution', 'cause': cause, 'subjectId': None,
                     'predicateId': None,
                     'inputRefs': K.cset([XI] + originating),
                     'evidenceKind': None, 'nativeCause': co['nativeCause'],
                     'universe': co['universe']})
    if budget_exhausted:
        rows.append({'source': 'execution', 'cause': 'work-budget-exhausted',
                     'subjectId': None, 'predicateId': None, 'inputRefs': EI,
                     'evidenceKind': None, 'nativeCause': None, 'universe': None})
    return K.cset(rows)

